random.seed(0)
groups={'person':['Albert Einstein','Marie Curie','Isaac Newton','Charles Darwin','Ada Lovelace','Alan Turing','William Shakespeare','Jane Austen','Mark Twain','Nelson Mandela','Mahatma Gandhi','Leonardo da Vinci','Vincent van Gogh','Wolfgang Amadeus Mozart','Ludwig van Beethoven','Michael Jordan','Serena Williams','Lionel Messi','Barack Obama','Angela Merkel'], 'organization':['Microsoft','Google','Apple Inc','International Monetary Fund','United Nations','World Health Organization','European Union','World Bank','NASA','UNESCO','Red Cross','Amnesty International','Greenpeace','Toyota','Samsung','IBM','Intel','Amazon','Harvard University','Stanford University'], 'location':['Paris','London','Tokyo','Berlin','Rome','Madrid','Beijing','Sydney','Moscow','Cairo','New York','Los Angeles','Mount Everest','Sahara Desert','Pacific Ocean','Atlantic Ocean','Grand Canyon','Lake Victoria','South Africa','New Zealand']}
